import { AfterContentChecked, ChangeDetectorRef, Component, ElementRef, EventEmitter, inject, Input, Output, ViewChild } from '@angular/core';
import { ApplicationConfig, MODULE_NAME } from 'espd-common/config';
import { SettingService, SettingType } from 'espd-common/setting';

@Component({
    selector: 'espd-header',
    templateUrl: 'header.component.html',
    styleUrls: ['header.component.scss'],
    exportAs: 'header',
    standalone: false
})
export class HeaderComponent implements AfterContentChecked {

	@Input() applicationNameDisplay: boolean = true;
	@Input() subtitle: string = '';
	@Input() lockupRoute?: string;
	@Input() lockupHref?: string;
	@Input() customHeaderOnly: boolean = false;
	@Input() user?: { username: string, initials: string };
	@Output() lockupClicked: EventEmitter<void> = new EventEmitter();
	@Output() mobileMenuClicked: EventEmitter<boolean> = new EventEmitter<boolean>();

	@ViewChild('mobileMenuRef') mobileMenuRef?: ElementRef<HTMLElement>;

	public applicationName?: string;
	public logoUrl?: string;
	public logoMobileUrl?: string;
	public logoDisplay: boolean = true;
	public customHeader: string = '';
	public mobileMenuOpen: boolean = false;

	private changeDetector = inject(ChangeDetectorRef);

	constructor(settingService: SettingService, appConfig: ApplicationConfig) {
		settingService.waitFor(MODULE_NAME).subscribe(() => {
			this.customHeader = settingService.get(SettingType.CUSTOM_HEADER) || '';
			this.applicationName = settingService.get(appConfig.applicationNameSetting);
			this.logoUrl = settingService.get(SettingType.LOGO_URL);
			this.logoMobileUrl = settingService.get(SettingType.LOGO_URL_MOBILE);
			this.logoDisplay = settingService.get(SettingType.LOGO_DISPLAY);
		});
	}

	public ngAfterContentChecked(): void {
		// Because mobileMenuRef is assigned during content init,
		// and it is not marked as static anymore,
		// we need to detect changes to prevent changeAfterChecked errors
		// on the hasMobileContent field
		this.changeDetector.detectChanges();
	}

	public get hasMobileContent(): boolean {
		// If there are no children, there was no mobile menu content projected
		// and therefore we shouldn't show the mobile menu toggle button.
		return !!this.mobileMenuRef?.nativeElement.children.length;
	}

	public headerClicked(): void {
		this.lockupClicked.emit();
	}

	public mobileClicked(): void {
		this.mobileMenuOpen = !this.mobileMenuOpen;
		this.mobileMenuClicked.emit(this.mobileMenuOpen);
	}

	public closeMobileMenu(): void {
		this.mobileMenuOpen = false;
		this.mobileMenuClicked.emit(this.mobileMenuOpen);
	}
}